escenas.Mundo:
// Mundo compartido: «Tu llave gotea y apretarla más la empeora».
// Maqueta de baño: gabinete de madera abierto (llaves de paso a la vista), mesón con lavamanos
// y una llave de compresión 3D grande con manija en cruz. Agua 2D y flechas azules.
// paso 0-1: llave cerrada a la fuerza y gota cayendo del pico; llaves de paso abiertas.
// paso 2-3: la llave en corte transparente: vástago, zapata de goma negra, asiento dorado y agua abajo.
// paso 4: zapata aplastada (naranja, con el borde roto) y asiento con rayas rojas.
// paso 5: además, el hilo de agua que se cuela por el hueco (flechas azules) y la gota.
// paso 6: llaves de paso cerradas, la llave vacía y el pico seco.
// paso 7: manija a un lado en el mesón, tuerca aflojada (vástago algo subido) y llave ajustable en el gabinete.
// paso 8: vástago fuera, acostado en el mesón, con la zapata vieja a la vista.
// paso 9: igual, pero con la zapata nueva negra atornillada (destornillador en el gabinete).
// paso 10-11: todo armado, llave cromada sin corte, llaves de paso abiertas y pico seco.
import React from 'react';
import {Pieza, Flecha, Brillo} from '../lib3d';
import type {Paleta, V3} from '../lib3d';
import {Habitacion, Agua, Efecto, Tuberia, Sombra, Planta} from '../lib25d';

export const PARTES = [
  'lavamanos', 'gabinete', 'cuerpo', 'pico', 'asiento', 'rayas', 'zapata', 'tornillo', 'vastago',
  'tuerca', 'manija', 'agua', 'fuga', 'gota', 'llavesdepaso', 'tubos', 'llaveajustable', 'destornillador',
] as const;

export type ParteProps = {paleta: Paleta; resaltado?: boolean; frame?: number};
export type MundoProps = {paso: number; frame: number; fps: number; paleta: Paleta; ocultar?: string[]; resaltar?: string[]};

const PI = Math.PI;
const FPS = 30;
const S = 1.5; // la llave va agrandada en la maqueta
const BASE: V3 = [0, 0.82, -0.25]; // pie de la llave sobre el mesón
const W = (p: V3): V3 => [BASE[0] + p[0] * S, BASE[1] + p[1] * S, BASE[2] + p[2] * S];

const CROMO = '#CDD7DF';
const CROMO_OSC = '#8E9AA5';
const LATON = '#C9A25A';
const DORADO = '#D9A441';
const GOMA = '#2B2B30';
const ROJO = '#D63B2E';
const RAYA = '#E0402A';

/** Puntos clave en el mundo, para flechas, etiquetas, manos y cámara. */
export const PUNTOS = {
  pico: W([0, 0.17, 0.25]),
  manija: W([0, 0.5, 0]),
  tuerca: W([0, 0.325, 0]),
  vastago: W([0, 0.3, 0]),
  zapata: W([0, 0.142, 0]),
  asiento: W([0, 0.12, 0]),
  llavesDePaso: [[-0.22, 0.3, -0.28], [0.22, 0.3, -0.28]] as V3[],
  vastagoFuera: [0.47, 0.925, -0.05] as V3,
  zapataFuera: [0.47, 0.925, 0.16] as V3,
  manijaFuera: [-0.42, 0.87, 0.08] as V3,
};
const PIVOTE = PUNTOS.vastago;

// Estados por paso (la escena anima el cambio entre un paso y el siguiente).
export const corteLlave = (paso: number) => (paso >= 2 && paso <= 9 ? 1 : 0);
export const aperturaPaso = (paso: number) => (paso <= 5 || paso >= 10 ? 1 : 0);
export const gotea = (paso: number) => paso <= 5;
export const estadoZapata = (paso: number): 'normal' | 'aplastada' | 'nueva' =>
  paso >= 9 ? 'nueva' : paso >= 4 ? 'aplastada' : 'normal';

const col = (p: ParteProps, color: string) => (p.resaltado ? p.paleta.acentos[2] : color);

const EnLlave: React.FC<{children?: React.ReactNode}> = ({children}) => (
  <group position={BASE} scale={S}>{children}</group>
);

/** Lleva una parte (dibujada en su sitio final) a otro lugar: el punto `de` queda en `a`. */
export const Mover: React.FC<{de: V3; a: V3; rot?: V3; giro?: number; children?: React.ReactNode}> = ({de, a, rot = [0, 0, 0], giro = 0, children}) => (
  <group position={a} rotation={[0, giro, 0]}>
    <group rotation={rot}>
      <group position={[-de[0], -de[1], -de[2]]}>{children}</group>
    </group>
  </group>
);

// ---------- Lugar ----------
export const Lavamanos: React.FC<ParteProps> = (p) => (
  <group>
    <Pieza forma="caja" medidas={[1.3, 0.04, 0.66]} color={col(p, '#F4EFE6')} posicion={[0, 0.8, -0.05]} />
    <Pieza forma="caja" medidas={[1.3, 0.3, 0.03]} color="#DCEBEE" posicion={[0, 0.97, -0.395]} />
    <Pieza forma="caja" medidas={[1.3, 0.008, 0.01]} color="#B9CDD2" posicion={[0, 0.97, -0.378]} contorno={false} />
    {[-0.43, 0, 0.43].map((x) => (
      <Pieza key={x} forma="caja" medidas={[0.008, 0.3, 0.01]} color="#B9CDD2" posicion={[x + 0.215, 0.97, -0.378]} contorno={false} />
    ))}
    {/* lavamanos de sobreponer */}
    <Pieza forma="cilindro" medidas={[0.25, 0.18, 0.15]} color={col(p, '#FBFAF7')} posicion={[0, 0.895, 0.06]} />
    <Pieza forma="cilindro" medidas={[0.215, 0.215, 0.006]} color="#D6E3EA" posicion={[0, 0.971, 0.06]} />
    <Pieza forma="cilindro" medidas={[0.03, 0.03, 0.006]} color="#6F7A84" posicion={[0, 0.976, 0.06]} />
    {/* jabonera */}
    <Pieza forma="cilindro" medidas={[0.07, 0.06, 0.02]} color="#E9E1D3" posicion={[-0.5, 0.83, -0.27]} />
    <Pieza forma="capsula" medidas={[0.03, 0.05]} color="#F2B8A0" posicion={[-0.5, 0.865, -0.27]} rotacion={[0, 0.3, PI / 2]} />
  </group>
);

export const Gabinete: React.FC<ParteProps> = (p) => {
  const madera = col(p, p.paleta.acentos[4]);
  const puerta = (lado: 1 | -1) => (
    <group position={[-0.585 * lado, 0, 0.205]} rotation={[0, -1.9 * lado, 0]}>
      <Pieza forma="caja" medidas={[0.57, 0.64, 0.025]} color={col(p, '#EBD5B2')} posicion={[0.285 * lado, 0.42, 0]} />
      <Pieza forma="caja" medidas={[0.44, 0.5, 0.01]} color={madera} posicion={[0.285 * lado, 0.42, 0.016]} />
      <Pieza forma="esfera" medidas={[0.022]} color={CROMO} posicion={[0.52 * lado, 0.45, 0.035]} />
    </group>
  );
  return (
    <group>
      <Pieza forma="caja" medidas={[1.12, 0.06, 0.5]} color="#8A6444" posicion={[0, 0.03, -0.1]} />
      <Pieza forma="caja" medidas={[1.16, 0.03, 0.52]} color="#E2CFAF" posicion={[0, 0.075, -0.085]} />
      {[-1, 1].map((l) => (
        <Pieza key={l} forma="caja" medidas={[0.03, 0.72, 0.55]} color={madera} posicion={[0.585 * l, 0.42, -0.08]} />
      ))}
      <Pieza forma="caja" medidas={[1.16, 0.72, 0.02]} color="#EADBC2" posicion={[0, 0.42, -0.345]} />
      <Pieza forma="caja" medidas={[1.2, 0.06, 0.03]} color={madera} posicion={[0, 0.75, 0.195]} />
      {puerta(1)}
      {puerta(-1)}
    </group>
  );
};

// ---------- La llave de compresión ----------
export const Cuerpo: React.FC<ParteProps & {corte?: boolean}> = (p) => {
  const k = col(p, CROMO);
  return (
    <EnLlave>
      <Pieza forma="cilindro" medidas={[0.09, 0.1, 0.03]} color={k} posicion={[0, 0.015, 0]} />
      <Pieza forma="cilindro" medidas={[0.085, 0.085, 0.3]} color={p.corte ? '#CFEAF7' : k} posicion={[0, 0.15, 0]} opacidad={p.corte ? 0.28 : 1} contorno={!p.corte} />
      <Pieza forma="cilindro" medidas={[0.03, 0.036, 0.09]} color={CROMO_OSC} posicion={[0, 0.07, 0]} />
      {p.corte ? (
        [0.03, 0.3].map((y) => (
          <Pieza key={y} forma="toro" medidas={[0.085, 0.004]} color="#2B241D" posicion={[0, y, 0]} rotacion={[PI / 2, 0, 0]} contorno={false} />
        ))
      ) : (
        <Pieza forma="caja" medidas={[0.012, 0.22, 0.005]} color="#FFFFFF" posicion={[-0.04, 0.15, 0.074]} rotacion={[0, -0.5, 0]} contorno={false} />
      )}
    </EnLlave>
  );
};

export const Pico: React.FC<ParteProps & {corte?: boolean}> = (p) => {
  const k = col(p, CROMO);
  const op = p.corte ? 0.35 : 1;
  return (
    <EnLlave>
      <Pieza forma="cilindro" medidas={[0.032, 0.036, 0.2]} color={k} posicion={[0, 0.24, 0.15]} rotacion={[PI / 2, 0, 0]} opacidad={op} contorno={!p.corte} />
      <Pieza forma="esfera" medidas={[0.034]} color={k} posicion={[0, 0.24, 0.25]} opacidad={op} contorno={!p.corte} />
      <Pieza forma="cilindro" medidas={[0.03, 0.028, 0.06]} color={k} posicion={[0, 0.2, 0.25]} opacidad={op} contorno={!p.corte} />
      <Pieza forma="toro" medidas={[0.028, 0.006]} color="#5E6872" posicion={[0, 0.172, 0.25]} rotacion={[PI / 2, 0, 0]} />
      {!p.corte ? <Pieza forma="caja" medidas={[0.008, 0.008, 0.14]} color="#FFFFFF" posicion={[-0.012, 0.268, 0.15]} contorno={false} /> : null}
    </EnLlave>
  );
};

export const Asiento: React.FC<ParteProps> = (p) => (
  <EnLlave>
    <Pieza forma="toro" medidas={[0.036, 0.011]} color={col(p, DORADO)} posicion={[0, 0.12, 0]} rotacion={[PI / 2, 0, 0]} />
  </EnLlave>
);

export const Rayas: React.FC<ParteProps> = (p) => (
  <EnLlave>
    {[0.4, 1.3, 2.4].map((a) => (
      <Pieza key={a} forma="caja" medidas={[0.02, 0.004, 0.004]} color={col(p, RAYA)} brillo={RAYA} intensidadBrillo={0.4}
        posicion={[Math.cos(a) * 0.036, 0.131, Math.sin(a) * 0.036]} rotacion={[0, -a + PI / 2, 0]} contorno={false} />
    ))}
  </EnLlave>
);

export const Zapata: React.FC<ParteProps & {estado?: 'normal' | 'aplastada' | 'nueva'}> = (p) => {
  const estado = p.estado ?? 'nueva';
  const aplastada = estado === 'aplastada';
  const color = aplastada ? p.paleta.acentos[0] : estado === 'nueva' ? '#141417' : GOMA;
  return (
    <EnLlave>
      <Pieza forma="cilindro" medidas={[0.042, 0.042, 0.022]} color={col(p, color)} posicion={[0, aplastada ? 0.137 : 0.142, 0]}
        escala={aplastada ? [1.22, 0.55, 1.22] : 1} />
      {aplastada ? (
        <Pieza forma="caja" medidas={[0.018, 0.016, 0.016]} color={GOMA} posicion={[0.05, 0.137, 0.012]} rotacion={[0, 0.5, 0.3]} />
      ) : null}
      {estado === 'nueva' ? (
        <Pieza forma="caja" medidas={[0.03, 0.003, 0.004]} color="#FFFFFF" posicion={[-0.01, 0.154, 0.03]} contorno={false} />
      ) : null}
    </EnLlave>
  );
};

export const Tornillo: React.FC<ParteProps> = (p) => (
  <EnLlave>
    <Pieza forma="cilindro" medidas={[0.012, 0.012, 0.006]} color={col(p, CROMO_OSC)} posicion={[0, 0.127, 0]} />
    <Pieza forma="caja" medidas={[0.018, 0.002, 0.003]} color="#2B241D" posicion={[0, 0.1238, 0]} contorno={false} />
  </EnLlave>
);

export const Vastago: React.FC<ParteProps> = (p) => {
  const k = col(p, LATON);
  return (
    <EnLlave>
      <Pieza forma="cilindro" medidas={[0.045, 0.045, 0.012]} color={k} posicion={[0, 0.159, 0]} />
      <Pieza forma="cilindro" medidas={[0.024, 0.024, 0.31]} color={k} posicion={[0, 0.31, 0]} />
      {[0.18, 0.21, 0.24, 0.27, 0.3].map((y) => (
        <Pieza key={y} forma="toro" medidas={[0.025, 0.005]} color={k} posicion={[0, y, 0]} rotacion={[PI / 2, 0, 0]} contorno={false} />
      ))}
      <Pieza forma="cilindro" medidas={[0.019, 0.019, 0.04, 8]} color={k} posicion={[0, 0.48, 0]} />
    </EnLlave>
  );
};

export const Tuerca: React.FC<ParteProps> = (p) => (
  <EnLlave>
    <Pieza forma="cilindro" medidas={[0.07, 0.07, 0.05, 6]} color={col(p, CROMO)} posicion={[0, 0.325, 0]} />
    <Pieza forma="cilindro" medidas={[0.045, 0.05, 0.02]} color={col(p, CROMO)} posicion={[0, 0.36, 0]} />
  </EnLlave>
);

export const Manija: React.FC<ParteProps> = (p) => {
  const k = col(p, CROMO);
  return (
    <EnLlave>
      <group rotation={[0, PI / 4, 0]}>
        <Pieza forma="cilindro" medidas={[0.035, 0.042, 0.07]} color={k} posicion={[0, 0.49, 0]} />
        <Pieza forma="media_esfera" medidas={[0.035]} color={k} posicion={[0, 0.525, 0]} />
        <Pieza forma="cilindro" medidas={[0.018, 0.018, 0.008]} color={p.paleta.acentos[0]} posicion={[0, 0.56, 0]} />
        {[0, 1, 2, 3].map((i) => {
          const a = (i * PI) / 2;
          return (
            <group key={i} rotation={[0, a, 0]}>
              <Pieza forma="capsula" medidas={[0.016, 0.09]} color={k} posicion={[0.08, 0.495, 0]} rotacion={[0, 0, PI / 2]} />
              <Pieza forma="esfera" medidas={[0.027]} color={k} posicion={[0.135, 0.495, 0]} />
            </group>
          );
        })}
      </group>
    </EnLlave>
  );
};

// ---------- Agua (2D) ----------
const RUTA: V3[] = [[0.04, 0.135, 0.05], [0.04, 0.24, 0.06], [0, 0.24, 0.25], [0, 0.17, 0.25]];
const enRuta = (t: number): V3 => {
  const s = Math.min(0.999, Math.max(0, t)) * (RUTA.length - 1);
  const i = Math.floor(s);
  const f = s - i;
  const a = RUTA[i];
  const b = RUTA[i + 1];
  return [a[0] + (b[0] - a[0]) * f, a[1] + (b[1] - a[1]) * f, a[2] + (b[2] - a[2]) * f];
};

export const AguaInterior: React.FC<ParteProps & {fuga?: boolean}> = (p) => (
  <EnLlave>
    <Agua ancho={0.12} alto={0.1} posicion={[0, 0.07, 0.045]} nivel={0.95} fuga={p.fuga ? [0.75, 1] : null} fuerzaFuga={0.6}
      frame={p.frame ?? 0} fps={FPS} />
  </EnLlave>
);

export const Fuga: React.FC<ParteProps> = (p) => {
  const azul = p.paleta.acentos[2];
  const f = p.frame ?? 0;
  return (
    <EnLlave>
      <Flecha desde={RUTA[0]} hasta={[0.04, 0.215, 0.055]} color={azul} grosor={0.007} />
      <Flecha desde={[0.03, 0.24, 0.08]} hasta={[0, 0.24, 0.225]} color={azul} grosor={0.007} />
      <Flecha desde={[0, 0.215, 0.25]} hasta={[0, 0.16, 0.25]} color={azul} grosor={0.007} />
      <Brillo posicion={enRuta((f % 36) / 36)} color={azul} radio={0.01} />
      <Brillo posicion={enRuta(((f + 18) % 36) / 36)} color={azul} radio={0.008} />
    </EnLlave>
  );
};

export const Gota: React.FC<ParteProps> = (p) => (
  <Efecto tipo="gotas" posicion={[PUNTOS.pico[0], PUNTOS.pico[1] - 0.08, PUNTOS.pico[2] + 0.02]} tam={0.3}
    color={p.resaltado ? p.paleta.acentos[3] : p.paleta.acentos[2]} frame={p.frame ?? 0} fps={FPS} />
);

// ---------- Bajo el lavamanos ----------
export const LlavesDePaso: React.FC<ParteProps & {abierta?: number}> = (p) => {
  const giro = (1 - (p.abierta ?? 1)) * (PI / 2);
  return (
    <group>
      {PUNTOS.llavesDePaso.map((q, i) => (
        <group key={i} position={q}>
          <Pieza forma="esfera" medidas={[0.04]} color={col(p, CROMO)} />
          <Pieza forma="cilindro" medidas={[0.02, 0.02, 0.06]} color={col(p, CROMO)} posicion={[0, 0.045, 0]} />
          <Pieza forma="cilindro" medidas={[0.012, 0.012, 0.05]} color={CROMO_OSC} posicion={[0, 0, 0.05]} rotacion={[PI / 2, 0, 0]} />
          <Pieza forma="caja" medidas={[0.11, 0.035, 0.025]} color={col(p, '#F3F6F8')} posicion={[0, 0, 0.08]} rotacion={[0, 0, giro]} />
        </group>
      ))}
    </group>
  );
};

export const Tubos: React.FC<ParteProps & {flujo?: number}> = (p) => (
  <group>
    {[-1, 1].map((l) => (
      <group key={l}>
        <Tuberia puntos={[[0.22 * l, 0.09, -0.32], [0.22 * l, 0.3, -0.32], [0.22 * l, 0.3, -0.29]]} radio={0.025}
          color={col(p, '#C9824F')} flujo={p.flujo ?? 0} colorFlujo={p.paleta.acentos[2]} frame={p.frame ?? 0} fps={FPS} />
        <Tuberia puntos={[[0.22 * l, 0.34, -0.28], [0.08 * l, 0.6, -0.27], [0.03 * l, 0.79, -0.25]]} radio={0.016}
          color={col(p, '#BFC8CF')} flujo={p.flujo ?? 0} colorFlujo={p.paleta.acentos[2]} frame={p.frame ?? 0} fps={FPS} />
      </group>
    ))}
  </group>
);

/** Llave ajustable roja, acostada en el fondo del gabinete. */
export const LlaveAjustable: React.FC<ParteProps> = (p) => {
  const k = col(p, ROJO);
  return (
    <group position={[0.12, 0.105, -0.02]} rotation={[0, 0.35, 0]}>
      <Pieza forma="caja" medidas={[0.38, 0.025, 0.065]} color={k} />
      <Pieza forma="caja" medidas={[0.1, 0.03, 0.15]} color={CROMO} posicion={[0.23, 0, 0]} />
      <Pieza forma="caja" medidas={[0.07, 0.03, 0.035]} color={CROMO} posicion={[0.3, 0, 0.055]} />
      <Pieza forma="caja" medidas={[0.07, 0.03, 0.035]} color={CROMO} posicion={[0.3, 0, -0.04]} />
      <Pieza forma="cilindro" medidas={[0.018, 0.018, 0.05, 10]} color={CROMO_OSC} posicion={[0.2, 0, 0]} rotacion={[PI / 2, 0, 0]} />
    </group>
  );
};

/** Destornillador naranja, acostado en el gabinete. */
export const Destornillador: React.FC<ParteProps> = (p) => (
  <group position={[-0.25, 0.11, 0.0]} rotation={[0, -0.4, PI / 2]}>
    <Pieza forma="capsula" medidas={[0.025, 0.11]} color={col(p, p.paleta.acentos[0])} />
    <Pieza forma="cilindro" medidas={[0.008, 0.008, 0.16]} color={CROMO} posicion={[0, -0.15, 0]} />
  </group>
);

// ---------- El mundo según el paso ----------
export const Mundo: React.FC<MundoProps> = ({paso, frame, paleta, ocultar = [], resaltar = []}) => {
  const ve = (n: string) => !ocultar.includes(n);
  const pp = (n: string): ParteProps => ({paleta, frame, resaltado: resaltar.includes(n)});
  const corte = corteLlave(paso) > 0;
  const manijaFuera = paso >= 7 && paso <= 9;
  const vFuera = paso === 8 || paso === 9;
  const floja = paso === 7;
  const conAgua = paso >= 2 && paso <= 5;

  const marco = (hijo: React.ReactNode) =>
    vFuera ? (
      <Mover de={PIVOTE} a={PUNTOS.vastagoFuera} rot={[-PI / 2, 0, 0]} giro={0.3}>{hijo}</Mover>
    ) : floja ? (
      <Mover de={PIVOTE} a={[PIVOTE[0], PIVOTE[1] + 0.05, PIVOTE[2]]} rot={[0, 1.4, 0]}>{hijo}</Mover>
    ) : (
      hijo
    );

  return (
    <group>
      <Habitacion />
      <Planta posicion={[-0.95, 0, -0.2]} alto={0.8} frame={frame} fps={FPS} />
      <Sombra posicion={[-0.95, 0, -0.2]} radio={0.25} />
      <Sombra posicion={[0, 0, -0.08]} radio={0.8} />

      {ve('gabinete') ? <Gabinete {...pp('gabinete')} /> : null}
      {ve('lavamanos') ? <Lavamanos {...pp('lavamanos')} /> : null}
      {ve('tubos') ? <Tubos {...pp('tubos')} flujo={gotea(paso) ? 0.5 : 0} /> : null}
      {ve('llavesdepaso') ? <LlavesDePaso {...pp('llavesdepaso')} abierta={aperturaPaso(paso)} /> : null}
      {ve('llaveajustable') && paso >= 7 && paso <= 9 ? <LlaveAjustable {...pp('llaveajustable')} /> : null}
      {ve('destornillador') && paso === 9 ? <Destornillador {...pp('destornillador')} /> : null}

      {/* interior de la llave (se ve en el corte) */}
      {ve('agua') && conAgua ? <AguaInterior {...pp('agua')} fuga={paso === 5} /> : null}
      {ve('asiento') ? <Asiento {...pp('asiento')} /> : null}
      {ve('rayas') && paso >= 4 && paso <= 9 ? <Rayas {...pp('rayas')} /> : null}
      {ve('fuga') && paso === 5 ? <Fuga {...pp('fuga')} /> : null}

      {/* vástago con su zapata, tornillo y tuerca (salen juntos) */}
      {marco(
        <group>
          {ve('vastago') ? <Vastago {...pp('vastago')} /> : null}
          {ve('zapata') ? <Zapata {...pp('zapata')} estado={estadoZapata(paso)} /> : null}
          {ve('tornillo') ? <Tornillo {...pp('tornillo')} /> : null}
          {ve('tuerca') ? <Tuerca {...pp('tuerca')} /> : null}
        </group>,
      )}

      {ve('cuerpo') ? <Cuerpo {...pp('cuerpo')} corte={corte} /> : null}
      {ve('pico') ? <Pico {...pp('pico')} corte={corte} /> : null}

      {ve('manija') ? (
        manijaFuera ? (
          <Mover de={PUNTOS.manija} a={PUNTOS.manijaFuera} giro={0.4}>
            <Manija {...pp('manija')} />
          </Mover>
        ) : (
          <Manija {...pp('manija')} />
        )
      ) : null}

      {ve('gota') && gotea(paso) ? <Gota {...pp('gota')} /> : null}
    </group>
  );
};

escenas.Escena2:
// Escena 3: «Por dentro, la punta del vástago lleva una zapata de goma que sella contra el asiento.»
// La llave se abre en corte transparente: se ve el vástago, la zapata en su punta y el asiento dorado.
// La zapata sube un poco, se resalta y baja a sellar contra el asiento. Termina igual que Mundo paso 3.
import React from 'react';
import {EscenaProps, Etiqueta, Flecha, Pieza, aparecer, momento, mover} from '../lib3d';
import {Efecto} from '../lib25d';
import {Mundo, Cuerpo, Pico, AguaInterior, Vastago, Zapata, Tornillo, Manija, PUNTOS} from './Mundo';

const PI = Math.PI;

export const Escena2: React.FC<EscenaProps> = ({frame, fps, duracion, palabras, paleta}) => {
  const [naranja, , resalte] = paleta.acentos;

  const tPor = momento(palabras, fps, 'Por', 1);
  const tVastago = momento(palabras, fps, 'vástago', Math.round(duracion * 0.27));
  const tZapata = momento(palabras, fps, 'zapata', Math.round(duracion * 0.44));
  const tGoma = momento(palabras, fps, 'goma', Math.round(duracion * 0.57));
  const tSella = momento(palabras, fps, 'sella', Math.round(duracion * 0.68));
  const tAsiento = momento(palabras, fps, 'asiento', Math.round(duracion * 0.84));

  // Corte: un anillo de luz barre el cuerpo de arriba abajo y lo deja transparente.
  const barrido = aparecer(frame, tPor, 14);
  const enCorte = frame >= tPor + 7;
  const yBarrido = 1.29 - barrido * 0.47;
  const verBarrido = barrido > 0 && barrido < 1;
  const agua = aparecer(frame, tPor + 8, 12);

  // El vástago (con manija, zapata y tornillo) sube un poco y luego baja a sellar.
  const dy = mover(
    frame,
    [tZapata, tZapata + 10, tSella - 6, tSella, tSella + 5, tSella + 10],
    [0, 0.065, 0.065, -0.006, 0.002, 0],
  );

  // Resaltes en el momento exacto de cada palabra (1 a 1,5 s).
  const enVentana = (t: number, largo = 40) => frame >= t && frame < t + largo;
  const rVastago = enVentana(tVastago, 38);
  const rZapata = enVentana(tZapata, 22) || enVentana(tGoma, 20);
  const rAsiento = enVentana(tAsiento, 40);

  // Textos (como mucho 2 a la vez).
  const eVastago = aparecer(frame, tVastago, 8) * (1 - aparecer(frame, tSella - 4, 8));
  const eZapata = aparecer(frame, tZapata, 8);
  const eAsiento = aparecer(frame, tAsiento, 8);

  // Fuerza de cierre y agua que queda abajo, frenada por el sello.
  const empuje = aparecer(frame, tSella - 8, 8) * (1 - aparecer(frame, tSella + 20, 10));
  const aguaFrena = aparecer(frame, tSella, 12);
  const golpe = frame >= tSella && frame < tSella + 14;
  const destelloGoma = frame >= tGoma && frame < tGoma + 14;

  const pp = {paleta, frame};
  const z = PUNTOS.zapata;
  const a = PUNTOS.asiento;
  const v = PUNTOS.vastago;

  return (
    <group>
      <Mundo
        paso={2}
        frame={frame}
        fps={fps}
        paleta={paleta}
        ocultar={['cuerpo', 'pico', 'agua', 'vastago', 'zapata', 'tornillo', 'manija', 'asiento']}
        resaltar={[]}
      />

      {/* asiento dorado (se resalta al nombrarlo) */}
      <AsientoLocal paleta={paleta} resaltado={rAsiento} />

      {/* agua 2D adentro, aparece con el corte */}
      {agua > 0 ? (
        <group scale={[1, Math.max(0.01, agua), 1]} position={[0, (1 - agua) * 0.82, 0]}>
          <AguaInterior {...pp} />
        </group>
      ) : null}

      {/* vástago + zapata + tornillo + manija, juntos */}
      <group position={[0, dy, 0]}>
        <Vastago {...pp} resaltado={rVastago} />
        <Zapata {...pp} estado="normal" resaltado={rZapata} />
        <Tornillo {...pp} resaltado={rZapata} />
        <Manija {...pp} />
      </group>

      {/* cuerpo y pico: sólidos al inicio, en corte después del barrido */}
      <Cuerpo {...pp} corte={enCorte} />
      <Pico {...pp} corte={enCorte} />

      {verBarrido ? (
        <Pieza forma="toro" medidas={[0.14, 0.007]} color={resalte} brillo={resalte} intensidadBrillo={1.2}
          posicion={[0, yBarrido, -0.25]} rotacion={[PI / 2, 0, 0]} contorno={false} />
      ) : null}
      {frame >= tPor + 6 && frame < tPor + 20 ? (
        <Efecto tipo="destello" posicion={[0, 1.08, -0.05]} tam={0.45} color="#FFFFFF" frame={frame - tPor} fps={fps} />
      ) : null}

      {/* destello de la goma */}
      {destelloGoma ? (
        <Efecto tipo="destello" posicion={[z[0] + 0.02, z[1] + dy, z[2] + 0.16]} tam={0.22} color={naranja} frame={frame - tGoma} fps={fps} />
      ) : null}

      {/* fuerza de cierre: flecha naranja que empuja el vástago hacia abajo */}
      <Flecha desde={[0.3, 1.5, -0.2]} hasta={[0.3, 1.26, -0.2]} color={naranja} grosor={0.022} progreso={empuje} />

      {/* el agua sube y se frena en el sello */}
      <Flecha desde={[0, 0.875, -0.17]} hasta={[0, 0.975, -0.17]} color={resalte} grosor={0.011} progreso={aguaFrena} />
      {golpe ? (
        <Efecto tipo="ondas" posicion={[a[0], a[1] + 0.02, a[2] + 0.16]} tam={0.3} color={resalte} frame={frame - tSella} fps={fps} />
      ) : null}

      {/* etiquetas cortas a los lados */}
      <Etiqueta texto="vástago" punto={[v[0] - 0.035, v[1] + 0.02 + dy, v[2]]} desplazamiento={[-0.6, 0.3, 0.25]} escala={eVastago} />
      <Etiqueta texto="zapata" punto={[z[0] + 0.06, z[1] + dy, z[2] + 0.02]} desplazamiento={[0.55, 0.22, 0.3]} escala={eZapata} />
      <Etiqueta texto="asiento" punto={[a[0] - 0.05, a[1], a[2] + 0.02]} desplazamiento={[-0.6, -0.12, 0.3]} escala={eAsiento} />
    </group>
  );
};

/** Asiento dibujado aquí para poder resaltarlo (mismo lugar y forma que en Mundo). */
const AsientoLocal: React.FC<{paleta: EscenaProps['paleta']; resaltado?: boolean}> = ({paleta, resaltado}) => (
  <group position={[0, 0.82, -0.25]} scale={1.5}>
    <Pieza forma="toro" medidas={[0.036, 0.011]} color={resaltado ? paleta.acentos[2] : '#D9A441'}
      posicion={[0, 0.12, 0]} rotacion={[PI / 2, 0, 0]} />
  </group>
);

escenas.Escena1:
// Escena 2 · «Cierras fuerte, y la gota sigue. Entonces cierras más fuerte todavía.»
// 3D: la llave del Mundo (paso 1) y la manija que gira a la fuerza. 2D: la mano, la gota, las ondas.
import React from 'react';
import {EscenaProps, Pieza, Linea, Etiqueta, aparecer, momento, mover} from '../lib3d';
import {Mano, Efecto, Sombra} from '../lib25d';
import {Mundo, Manija, Mover, PUNTOS} from './Mundo';

const PI = Math.PI;

export const Escena1: React.FC<EscenaProps> = ({frame, fps, duracion, palabras, paleta}) => {
  const [naranja, , azul, mostaza] = paleta.acentos;

  const tCierras = momento(palabras, fps, 'cierras', 1);
  const tFuerte = momento(palabras, fps, 'fuerte', 13);
  const tGota = momento(palabras, fps, 'gota', 47);
  const tEntonces = momento(palabras, fps, 'entonces', 79);
  const tMas = momento(palabras, fps, 'más', 102);
  const tTodavia = momento(palabras, fps, 'todavía', 122);
  const tFin = duracion - 8;

  // Giro total = PI/2: la cruz queda igual que al inicio (enlace invisible con el paso 2).
  const giro = mover(
    frame,
    [tCierras, tFuerte, tFuerte + 6, tEntonces, tEntonces + 8, tMas, tMas + 10],
    [0, 0.55, 0.62, 0.62, 0.52, 1.25, PI / 2],
  );

  // Fuerza y temblor: primer apretón y, más fuerte, el segundo.
  const f1 = aparecer(frame, tFuerte, 4) * (1 - aparecer(frame, tFuerte + 22, 10));
  const f2 = aparecer(frame, tMas + 4, 4) * (1 - aparecer(frame, tTodavia + 16, 8));
  const fuerza = f1 + 2 * f2;
  const temblor = Math.sin(frame * 2.7) * 0.007 * fuerza;

  // La mano sale al final, para dejar paso al corte.
  const salida = aparecer(frame, tTodavia + 8, 12);
  const mano = PUNTOS.manija;
  const manoPos: [number, number, number] = [mano[0] + 0.24 + temblor + salida * 1.4, mano[1] + 0.03 + salida * 0.6, mano[2] + 0.3];

  const paso = frame >= tFin ? 2 : 1;
  const manijaResaltada = frame >= tMas && frame < tMas + 38;
  const gotaResaltada = frame >= tGota && frame < tGota + 36;

  // Líneas de esfuerzo alrededor de la manija.
  const esfuerzo = (amp: number) => {
    if (amp <= 0.01) return null;
    const c: [number, number, number] = [mano[0], mano[1] + 0.02, mano[2] + 0.2];
    return [2.2, 2.65, 3.1, 3.55, 0.75, 1.2].map((a, i) => {
      const r0 = 0.27 + 0.02 * Math.sin(frame * 0.9 + i);
      const r1 = r0 + 0.1 * amp;
      return (
        <Linea key={i} color={mostaza} grosor={0.009} brillo
          desde={[c[0] + Math.cos(a) * r0, c[1] + Math.sin(a) * r0, c[2]]}
          hasta={[c[0] + Math.cos(a) * r1, c[1] + Math.sin(a) * r1, c[2]]} />
      );
    });
  };

  // Flecha curva de giro (sentido de cierre), naranja.
  const flecha1 = aparecer(frame, tCierras, 8) * (1 - aparecer(frame, tEntonces - 4, 8));
  const flecha2 = aparecer(frame, tEntonces + 6, 8) * (1 - aparecer(frame, tTodavia + 10, 8));
  const flecha = Math.max(flecha1, flecha2 * 1.25);
  const th0 = 1.7;
  const largo = 1.6;
  const rArco = 0.34;

  const etiGota = aparecer(frame, tGota, 8) * (1 - aparecer(frame, tEntonces, 8));
  const etiFuerte = aparecer(frame, tMas, 8) * (1 - aparecer(frame, tFin - 6, 6));

  return (
    <group>
      <Mundo paso={paso} frame={frame} fps={fps} paleta={paleta}
        ocultar={paso === 1 ? ['manija'] : []} resaltar={gotaResaltada ? ['gota'] : []} />

      {/* La manija, girando a la fuerza y temblando */}
      {paso === 1 ? (
        <Mover de={mano} a={[mano[0] + temblor, mano[1], mano[2]]} giro={-giro}>
          <Manija paleta={paleta} resaltado={manijaResaltada} />
        </Mover>
      ) : null}

      {/* Delante: la mano que aprieta */}
      {salida < 1 ? (
        <Mano pose="agarra" posicion={manoPos} ancho={0.75} frame={frame} fps={fps} />
      ) : null}

      {esfuerzo(fuerza)}

      {/* Flecha de giro */}
      {flecha > 0.01 ? (
        <group position={[mano[0], mano[1] + 0.02, mano[2] + 0.22]} scale={flecha}>
          <Pieza forma="toro" medidas={[rArco, 0.018, largo]} color={naranja} rotacion={[0, 0, th0]} />
          <Pieza forma="cono" medidas={[0.05, 0.1]} color={naranja}
            posicion={[Math.cos(th0) * rArco + 0.04, Math.sin(th0) * rArco, 0]} rotacion={[0, 0, -PI / 2]} />
        </group>
      ) : null}

      {/* La gota sigue: ondas en el lavamanos */}
      <Efecto tipo="ondas" posicion={[0, 0.985, 0.12]} tam={0.28} color={azul} frame={frame} fps={fps} />

      {/* Delante: vaso con cepillo en el mesón */}
      <group position={[0.48, 0.82, 0.14]}>
        <Pieza forma="cilindro" medidas={[0.05, 0.042, 0.13]} color="#9FD3E0" posicion={[0, 0.065, 0]} />
        <Pieza forma="capsula" medidas={[0.012, 0.16]} color={naranja} posicion={[0.015, 0.19, 0]} rotacion={[0, 0, -0.2]} />
        <Pieza forma="caja" medidas={[0.025, 0.04, 0.02]} color="#F4EFE6" posicion={[0.035, 0.28, 0]} rotacion={[0, 0, -0.2]} />
        <Sombra posicion={[0, 0.005, 0]} radio={0.08} />
      </group>

      {/* Fondo: toalla colgada en la pared */}
      <group position={[0.55, 1.35, -0.38]}>
        <Pieza forma="cilindro" medidas={[0.012, 0.012, 0.34]} color="#CDD7DF" rotacion={[0, 0, PI / 2]} />
        <Pieza forma="caja" medidas={[0.28, 0.34, 0.025]} color="#F2C94C" posicion={[0, -0.17, 0.01]} />
        <Pieza forma="caja" medidas={[0.28, 0.03, 0.03]} color="#E9E1D3" posicion={[0, -0.29, 0.012]} />
      </group>

      <Etiqueta texto="la gota" punto={[PUNTOS.pico[0], PUNTOS.pico[1] - 0.04, PUNTOS.pico[2]]}
        desplazamiento={[-0.6, -0.12, 0.25]} escala={etiGota} />
      <Etiqueta texto="más fuerte" punto={[mano[0] - 0.16, mano[1], mano[2] + 0.05]}
        desplazamiento={[-0.42, 0.2, 0.3]} escala={etiFuerte} />

      {/* Destello que tapa el paso al corte */}
      {frame >= tFin - 4 ? (
        <Efecto tipo="destello" posicion={[0, 1.3, 0.35]} tam={0.5} color={azul} frame={frame - tFin} fps={fps} />
      ) : null}
    </group>
  );
};

escenas.Escena3:
// Escena 4: «Cada apretón de más aplasta la goma, y el borde del asiento puede ir rayándola.»
// 3D: la llave en corte (Mundo paso 3). El vástago y la manija bajan con fuerza y giran;
// la zapata se aplasta como una galleta; el asiento se resalta y aparecen las rayas rojas.
// 2D: la mano que aprieta, destellos y chispas. Termina igual que <Mundo paso={4} />.
import React from 'react';
import {interpolate, Easing} from 'remotion';
import {EscenaProps, Flecha, Etiqueta, aparecer, momento} from '../lib3d';
import {Mano, Efecto} from '../lib25d';
import {Mundo, Vastago, Zapata, Tornillo, Manija, Rayas, PUNTOS} from './Mundo';

const PI = Math.PI;
const C = {extrapolateLeft: 'clamp', extrapolateRight: 'clamp'} as const;

export const Escena3: React.FC<EscenaProps> = ({frame, fps, duracion, palabras, paleta}) => {
  const [naranja] = paleta.acentos;

  const tCada = momento(palabras, fps, 'cada', 1);
  const tMas = momento(palabras, fps, 'más', 34);
  const tApl = momento(palabras, fps, 'aplasta', 40);
  const tGoma = momento(palabras, fps, 'goma', 70);
  const tBorde = momento(palabras, fps, 'borde', 96);
  const tAsi = momento(palabras, fps, 'asiento', 110);
  const tRaya = momento(palabras, fps, 'rayándola', 142);
  const fin = Math.max(tRaya + 14, duracion - 16);

  // Tres apretones: anticipación (sube), golpe (baja) y asentamiento.
  const golpes = [
    {t: tCada + 8, amp: 0.02, sq: 0.15},
    {t: Math.max(tCada + 22, tMas - 10), amp: 0.025, sq: 0.15},
    {t: Math.max(tCada + 34, tApl + 2), amp: 0.045, sq: 0.7},
  ];
  let oy = 0;
  let giro = 0;
  let sq = 0;
  golpes.forEach(({t, amp, sq: s}) => {
    oy += interpolate(frame, [t - 8, t - 2, t, t + 3, t + 10], [0, amp, -0.012, -0.012, 0], {
      ...C,
      easing: Easing.inOut(Easing.cubic),
    });
    giro += interpolate(frame, [t - 8, t], [0, PI / 2], {...C, easing: Easing.in(Easing.quad)});
    sq += interpolate(frame, [t - 1, t + 2], [0, s], C);
  });
  const tFinal = golpes[2].t;
  const aplastada = frame >= tFinal + 3;
  // rebote de "galleta" justo al aplastarse
  const sobre = interpolate(frame, [tFinal, tFinal + 2, tFinal + 3], [0, 0.08, 0], C);
  const sy = 1 - 0.45 * Math.min(1, sq) - sobre;
  const sx = 1 + 0.22 * Math.min(1, sq) + sobre * 0.5;

  // Mano que aprieta la manija y se va después del golpe fuerte.
  const salida = aparecer(frame, tFinal + 10, 16);
  const manoX = 0.34 + salida * 1.4;
  const manoY = PUNTOS.manija[1] + 0.05 + oy * 1.5;

  // Flechas de fuerza hacia abajo (más... aplasta).
  const fuerza = aparecer(frame, tMas, 6) * (1 - aparecer(frame, tFinal + 22, 8));

  // Resaltes y textos.
  const zapataRes = frame >= tGoma && frame < tGoma + 40;
  const asientoRes = frame >= tBorde && frame < tBorde + 40;
  const salen = 1 - aparecer(frame, fin, 10);
  const etGoma = aparecer(frame, tGoma, 8) * salen;
  const etAsiento = aparecer(frame, tAsi, 8) * salen;
  const rayas = frame >= tRaya;

  // Pivote de la zapata: su base, sobre el asiento.
  const baseZ: [number, number, number] = [0, 0.82 + 0.131 * 1.5, -0.25];

  return (
    <group>
      <Mundo
        paso={3}
        frame={frame}
        fps={fps}
        paleta={paleta}
        ocultar={['vastago', 'zapata', 'tornillo', 'manija']}
        resaltar={asientoRes ? ['asiento'] : []}
      />

      {/* vástago + manija: bajan con fuerza y giran sobre su eje */}
      <group position={[0, oy, -0.25]} rotation={[0, giro, 0]}>
        <group position={[0, 0, 0.25]}>
          <Vastago paleta={paleta} />
          <Manija paleta={paleta} />
        </group>
      </group>

      {/* zapata + tornillo: bajan con el vástago y se aplastan */}
      <group position={[0, Math.min(0, oy), 0]}>
        {aplastada ? (
          <Zapata paleta={paleta} estado="aplastada" resaltado={zapataRes} />
        ) : (
          <group position={baseZ} scale={[sx, sy, sx]}>
            <group position={[-baseZ[0], -baseZ[1], -baseZ[2]]}>
              <Zapata paleta={paleta} estado="normal" resaltado={zapataRes} />
            </group>
          </group>
        )}
        <Tornillo paleta={paleta} />
      </group>

      {/* las rayas del asiento aparecen al decir "rayándola" */}
      {rayas ? <Rayas paleta={paleta} /> : null}

      {/* mano 2D que aprieta */}
      {salida < 1 ? (
        <Mano pose="agarra" posicion={[manoX, manoY, 0.05]} ancho={0.75} escala={1 - salida * 0.3} frame={frame} fps={fps} />
      ) : null}

      {/* fuerza del apretón */}
      {[-1, 1].map((l) => (
        <Flecha key={l} desde={[0.2 * l, 1.66, -0.15]} hasta={[0.2 * l, 1.22, -0.15]} color={naranja} grosor={0.022} progreso={fuerza} />
      ))}

      {/* golpe: destello en la zapata */}
      {frame >= tFinal && frame < tFinal + 18 ? (
        <Efecto tipo="destello" posicion={[0, PUNTOS.zapata[1], -0.08]} tam={0.35} frame={frame - tFinal} fps={fps} />
      ) : null}
      {/* el borde del asiento roza la goma */}
      {frame >= tBorde && frame < tBorde + 16 ? (
        <Efecto tipo="chispa" posicion={[0.06, PUNTOS.asiento[1], -0.17]} tam={0.18} color={paleta.acentos[3]} frame={frame - tBorde} fps={fps} />
      ) : null}
      {rayas && frame < tRaya + 20 ? (
        <Efecto tipo="chispa" posicion={[0.04, PUNTOS.asiento[1] + 0.01, -0.18]} tam={0.25} color="#E0402A" frame={frame - tRaya} fps={fps} />
      ) : null}

      {/* etiquetas */}
      <Etiqueta texto="la goma" punto={[0.06, PUNTOS.zapata[1], -0.2]} desplazamiento={[0.5, 0.3, 0.3]} escala={etGoma} />
      <Etiqueta texto="el asiento" punto={[-0.05, PUNTOS.asiento[1], -0.2]} desplazamiento={[-0.5, -0.2, 0.3]} escala={etAsiento} />
    </group>
  );
};

escenas.Escena0:
// Escena 1 (gancho): «Cuanto más aprietas esa llave, más desgastas por dentro la pieza que sella.»
// 3D: la llave de compresión del Mundo (manija que se retuerce y tiembla, cuerpo que se agrieta,
// corte transparente para ver la zapata aplastándose). 2D: la mano, la gota gigante y el agua.
import React from 'react';
import {interpolate, Easing} from 'remotion';
import {EscenaProps, Flecha, Etiqueta, Linea, aparecer, momento} from '../lib3d';
import type {V3} from '../lib3d';
import {Mano, Efecto} from '../lib25d';
import {Mundo, Manija, Zapata, Cuerpo, Pico, AguaInterior, Mover, PUNTOS} from './Mundo';

const PASO = 0;
const S = 1.5;
const Y0 = 0.82;
const RC = 0.087 * S; // radio de la superficie del cuerpo (grietas)
const ROJO = '#D63B2E';

// Grietas en el cromo: [ángulo alrededor del cuerpo, altura local de la llave]
const GRIETA: [number, number][] = [
  [0.5, 0.29], [0.62, 0.25], [0.44, 0.21], [0.64, 0.16], [0.5, 0.11], [0.68, 0.06],
];
const RAMA: [number, number][] = [[0.44, 0.21], [0.24, 0.18], [0.3, 0.13], [0.16, 0.09]];
const enCuerpo = ([a, y]: [number, number]): V3 => [Math.sin(a) * RC, Y0 + y * S, -0.25 + Math.cos(a) * RC];

export const Escena0: React.FC<EscenaProps> = ({frame, fps, duracion, palabras, paleta}) => {
  const [naranja, , azul, mostaza] = paleta.acentos;

  const tAprieta = momento(palabras, fps, 'aprietas', 24);
  const tLlave = momento(palabras, fps, 'llave', 56);
  const tDesgasta = momento(palabras, fps, 'desgastas', 84);
  const tDentro = momento(palabras, fps, 'dentro', 112);
  const tPieza = momento(palabras, fps, 'pieza', 127);
  const tSella = momento(palabras, fps, 'sella', 142);
  const fin = duracion;

  // Avance con rebasamiento (anticipación y asentamiento)
  const golpe = (t: number, d = 10) =>
    interpolate(frame, [t, t + d], [0, 1], {
      extrapolateLeft: 'clamp',
      extrapolateRight: 'clamp',
      easing: Easing.out(Easing.back(2.2)),
    });
  // Impulso que decae (salto, temblor fuerte)
  const impulso = (t: number, caida = 5) => (frame >= t ? Math.exp(-(frame - t) / caida) : 0);

  // Giro de la manija: cada apretón la retuerce más; termina a 90° (la cruz queda igual que en el Mundo)
  const giro =
    -0.14 * golpe(0, 7) -
    0.32 * golpe(tAprieta) -
    0.42 * golpe(tDesgasta) -
    (Math.PI / 2 - 0.88) * golpe(tPieza, 12);

  // Tensión: tiembla mientras se aprieta, se calma al final
  const tension = 1 - aparecer(frame, fin - 22, 14);
  const saltos = impulso(2) + impulso(tAprieta) + impulso(tLlave) + impulso(tDesgasta);
  const temblorX = Math.sin(frame * 2.7) * (0.004 + 0.012 * saltos) * tension;
  const temblorZ = Math.cos(frame * 3.3) * 0.004 * tension;
  const salto = 0.035 * Math.abs(Math.sin(frame * 0.9)) * saltos * tension;

  // Grietas rojas: se abren en tres golpes y desaparecen al abrir el corte
  const grieta = Math.min(1, 0.3 * aparecer(frame, 0, 6) + 0.35 * aparecer(frame, tAprieta, 10) + 0.35 * aparecer(frame, tLlave, 10));
  const corteOn = frame >= tDentro && frame < fin - 14;
  const verGrieta = frame < tDentro;

  // Resaltes al nombrar
  const resLlave = frame >= tLlave && frame < tLlave + 38;
  const resPieza = frame >= tPieza && frame < tPieza + 40;

  // Zapata que se aplasta con cada apretón (se ve dentro del corte) y vuelve a su forma
  const aplasta = (impulso(tPieza, 7) * 0.9 + impulso(tSella, 7) * 0.7) * (1 - aparecer(frame, fin - 16, 10));

  // Gota gigante que cuelga y cae, hasta quedar como la gota normal del Mundo
  const tamGota = interpolate(frame, [0, tSella, tSella + 16], [0.62, 0.55, 0.3], {extrapolateLeft: 'clamp', extrapolateRight: 'clamp'});

  // Mano: aprieta desde el fotograma 0 y se retira al final
  const sale = aparecer(frame, fin - 12, 10);
  const manoX = 0.22 + temblorX * 1.4 + 0.02 * Math.sin(giro * 2);
  const manoY = 1.6 + salto * 0.6 + sale * 0.55;

  // Textos y flechas
  const flechaAprieta = aparecer(frame, tAprieta, 8) * (1 - aparecer(frame, tDentro - 6, 6));
  const flechaZapata = aparecer(frame, tPieza - 2, 8) * (1 - aparecer(frame, fin - 16, 6));
  const etiqueta = aparecer(frame, tPieza, 8) * (1 - aparecer(frame, fin - 16, 8));

  const tramos = (pts: [number, number][], prog: number, k: string) => {
    const n = pts.length - 1;
    return pts.slice(0, -1).map((p, i) => {
      const local = Math.min(1, Math.max(0, prog * n - i));
      if (local <= 0) return null;
      return (
        <Linea key={k + i} desde={enCuerpo(p)} hasta={enCuerpo(pts[i + 1])} grosor={0.0065} color={ROJO} brillo progreso={local} />
      );
    });
  };

  const chispa = (t: number, p: V3, tipo: 'chispa' | 'destello' = 'chispa', tam = 0.35) =>
    frame >= t && frame < t + 12 ? (
      <Efecto key={`${tipo}${t}`} tipo={tipo} posicion={p} tam={tam} color={mostaza} frame={frame - t} fps={fps} />
    ) : null;

  const ocultar = ['manija', 'gota', 'zapata', ...(corteOn ? ['cuerpo', 'pico'] : [])];
  const resaltar = resLlave ? ['cuerpo', 'pico'] : [];

  return (
    <group>
      <Mundo paso={PASO} frame={frame} fps={fps} paleta={paleta} ocultar={ocultar} resaltar={resaltar} />

      {/* llave en corte transparente: se ve la zapata pisando el asiento */}
      {corteOn ? (
        <group>
          <AguaInterior paleta={paleta} frame={frame} />
          <Cuerpo paleta={paleta} corte />
          <Pico paleta={paleta} corte />
        </group>
      ) : null}

      {/* zapata (se aplasta con cada apretón) */}
      <group position={PUNTOS.zapata} scale={[1 + 0.2 * aplasta, 1 - 0.45 * aplasta, 1 + 0.2 * aplasta]}>
        <group position={[-PUNTOS.zapata[0], -PUNTOS.zapata[1], -PUNTOS.zapata[2]]}>
          <Zapata paleta={paleta} estado="normal" resaltado={resPieza} />
        </group>
      </group>

      {/* manija retorcida, temblando, a punto de saltar */}
      <Mover
        de={PUNTOS.manija}
        a={[PUNTOS.manija[0] + temblorX, PUNTOS.manija[1] + salto, PUNTOS.manija[2] + temblorZ]}
        rot={[temblorZ * 3, 0, temblorX * 4]}
        giro={giro}
      >
        <Manija paleta={paleta} resaltado={resLlave} />
      </Mover>

      {/* grietas rojas recorriendo el cromo */}
      {verGrieta ? (
        <group>
          {tramos(GRIETA, grieta, 'g')}
          {tramos(RAMA, Math.max(0, grieta - 0.35) / 0.65, 'r')}
        </group>
      ) : null}

      {/* crujidos: chispas y destellos en cada apretón */}
      {chispa(0, [0.06, 1.55, -0.12], 'destello', 0.45)}
      {chispa(tAprieta, enCuerpo(GRIETA[0]))}
      {chispa(tLlave, enCuerpo(GRIETA[3]))}
      {chispa(tDesgasta, [0.08, 1.6, -0.15], 'destello', 0.4)}
      {chispa(tDentro, [0.05, 1.1, -0.1], 'destello', 0.5)}
      {chispa(fin - 14, [0.05, 1.1, -0.1], 'destello', 0.4)}

      {/* fuerza del apretón sobre la manija */}
      <Flecha desde={[0.02, 1.88, -0.2]} hasta={[0.02, 1.71, -0.22]} color={mostaza} grosor={0.022} progreso={flechaAprieta} />

      {/* fuerza que baja hasta la zapata, por dentro */}
      <Flecha desde={[-0.2, 1.32, -0.08]} hasta={[-0.05, 1.07, -0.18]} color={naranja} grosor={0.02} progreso={flechaZapata} />
      <Etiqueta texto="pieza que sella" punto={[0.06, PUNTOS.zapata[1], -0.2]} desplazamiento={[0.5, 0.12, 0.25]} escala={etiqueta} />

      {/* gota gigante colgando del pico */}
      <Efecto
        tipo="gotas"
        posicion={[PUNTOS.pico[0], PUNTOS.pico[1] - 0.08, PUNTOS.pico[2] + 0.02]}
        tam={tamGota}
        color={azul}
        frame={frame}
        fps={fps}
      />
      {frame >= tSella + 6 && frame < tSella + 26 ? (
        <Efecto tipo="ondas" posicion={[0, 0.975, 0.06]} tam={0.3} color={azul} frame={frame - tSella - 6} fps={fps} />
      ) : null}

      {/* mano que aprieta (delante de la llave) */}
      {sale < 1 ? (
        <Mano pose="agarra" posicion={[manoX, manoY, 0.02]} ancho={0.72} escala={1 - sale} frame={frame} fps={fps} />
      ) : null}
    </group>
  );
};

escenas.Escena4:
// Escena 5: «Queda un huequito, y el agua se cuela. Muchas veces el problema no es la llave: es una pieza diminuta.»
// Base: Mundo paso 4 (zapata aplastada y asiento rayado en el corte). Termina como paso 5:
// el agua se cuela por el hueco (flechas azules), la gota sigue y la zapata queda señalada.
import React from 'react';
import {EscenaProps, Flecha, Etiqueta, Brillo, Linea, aparecer, desaparecer, momento, mover} from '../lib3d';
import type {V3} from '../lib3d';
import {Efecto} from '../lib25d';
import {Mundo, Zapata, AguaInterior, Fuga, PUNTOS} from './Mundo';

const PASO = 4;

export const Escena4: React.FC<EscenaProps> = ({frame, fps, duracion, palabras, paleta}) => {
  const [naranja, , azul, mostaza] = paleta.acentos;

  const tQueda = momento(palabras, fps, 'queda', 1);
  const tHueco = momento(palabras, fps, 'huequito', Math.round(0.77 * fps));
  const tAgua = momento(palabras, fps, 'agua', Math.round(1.69 * fps));
  const tCuela = momento(palabras, fps, 'cuela', Math.round(2.03 * fps));
  const tVeces = momento(palabras, fps, 'veces', Math.round(3.29 * fps));
  const tProblema = momento(palabras, fps, 'problema', Math.round(3.93 * fps));
  const tLlave = momento(palabras, fps, 'llave', Math.round(4.99 * fps));
  const tPieza = momento(palabras, fps, 'pieza', Math.round(5.95 * fps));
  const tDiminuta = momento(palabras, fps, 'diminuta', Math.round(6.29 * fps));

  // Puntos clave del corte
  const Z = PUNTOS.zapata;
  const A = PUNTOS.asiento;
  const hueco: V3 = [Z[0] + 0.06, (Z[1] + A[1]) / 2 - 0.005, Z[2] + 0.075];

  // Golpe 1 (Queda): destello en el hueco entre zapata y asiento
  const pulsoHueco = aparecer(frame, tQueda, 8) * (0.6 + 0.4 * Math.sin(frame / 3) ** 2);
  const verHueco = desaparecer(frame, tProblema, 10);

  // Golpe 2 (huequito): etiqueta del hueco
  const etiHueco = aparecer(frame, tHueco, 10) * desaparecer(frame, tProblema - 6, 10);

  // Golpe 3 (agua): el agua empieza a buscar el hueco; trazo punteado del camino
  const camino = aparecer(frame, tAgua, 12);
  const caminoFuera = desaparecer(frame, tCuela + 4, 8);
  const fugaActiva = frame >= tAgua;

  // Golpe 4 (cuela): las flechas del flujo del mundo (paso 5) y salpicadura en la taza
  const conFuga = frame >= tCuela;
  const ondas = frame >= tCuela + 6 && frame < tProblema;

  // Golpe 5 (veces): la gota se resalta
  const gotaRes = frame >= tVeces && frame < tVeces + Math.round(1.1 * fps);

  // Golpe 6 (llave): la llave se resalta: no es ella
  const llaveRes = frame >= tLlave && frame < tLlave + Math.round(0.9 * fps);

  // Golpe 7 (pieza): la zapata se resalta y la flecha naranja llega
  const zapRes = frame >= tPieza && frame < tPieza + Math.round(1.2 * fps);
  const flecha = aparecer(frame, tPieza - 6, 10);

  // Golpe 8 (diminuta): la zapata se agranda (sobre su propio centro) y vuelve; la flecha late
  const crece = mover(frame, [tDiminuta, tDiminuta + 8, tDiminuta + 22], [1, 1.7, 1]);
  const etiPieza = aparecer(frame, tDiminuta, 10);
  const latido = 1 + 0.15 * aparecer(frame, tDiminuta, 6) * Math.abs(Math.sin((frame - tDiminuta) / 4));

  const resaltar: string[] = [];
  if (gotaRes) resaltar.push('gota');
  if (llaveRes) resaltar.push('cuerpo', 'pico', 'manija');

  // Puntos punteados del camino del agua (mundo): hueco -> pico
  const p0 = hueco;
  const p1: V3 = [Z[0] + 0.06, PUNTOS.pico[1] + 0.105, Z[2] + 0.09];
  const p2: V3 = [PUNTOS.pico[0], PUNTOS.pico[1] + 0.105, PUNTOS.pico[2]];
  const avance = camino * 3;

  // Flecha naranja que señala la zapata desde arriba a la izquierda (zona vacía)
  const fDesde: V3 = [-0.55, 1.5, 0.15];
  const fHasta: V3 = [Z[0] - 0.09, Z[1] + 0.04, Z[2] + 0.06];

  return (
    <group>
      <Mundo paso={PASO} frame={frame} fps={fps} paleta={paleta} ocultar={['agua', 'zapata', 'fuga']} resaltar={resaltar} />

      {/* agua dentro del cuerpo: desde "agua" ya busca el hueco (igual que paso 5) */}
      <AguaInterior paleta={paleta} frame={frame} fuga={fugaActiva} />

      {/* zapata aplastada, con pulso de tamaño en "diminuta" */}
      <group position={Z} scale={crece}>
        <group position={[-Z[0], -Z[1], -Z[2]]}>
          <Zapata paleta={paleta} frame={frame} estado="aplastada" resaltado={zapRes} />
        </group>
      </group>

      {/* destello en el hueco */}
      {verHueco > 0.01 && pulsoHueco > 0.01 ? (
        <Brillo posicion={hueco} color={mostaza} radio={0.022 * pulsoHueco * verHueco} />
      ) : null}

      {/* camino punteado del agua mientras empieza a colarse */}
      {camino > 0.01 && caminoFuera > 0.01 ? (
        <group scale={1}>
          <Linea desde={p0} hasta={p1} color={azul} grosor={0.007} discontinua brillo progreso={Math.min(1, avance) * caminoFuera} />
          {avance > 1 ? <Linea desde={p1} hasta={p2} color={azul} grosor={0.007} discontinua brillo progreso={Math.min(1, avance - 1) * caminoFuera} /> : null}
        </group>
      ) : null}

      {/* flechas de la fuga y partículas por el hueco (estado final del paso 5) */}
      {conFuga ? <Fuga paleta={paleta} frame={frame} /> : null}

      {/* salpicadura en la taza mientras la gota cae */}
      {ondas ? <Efecto tipo="ondas" posicion={[0, 0.98, 0.06]} tam={0.3} color={azul} frame={frame - tCuela} fps={fps} /> : null}

      {/* flecha naranja hacia la culpable */}
      {flecha > 0.01 ? (
        <group position={fHasta} scale={latido}>
          <group position={[-fHasta[0], -fHasta[1], -fHasta[2]]}>
            <Flecha desde={fDesde} hasta={fHasta} color={naranja} grosor={0.028} progreso={flecha} />
          </group>
        </group>
      ) : null}

      {/* textos: como mucho uno a la vez aquí */}
      <Etiqueta texto="el hueco" punto={hueco} desplazamiento={[0.55, 0.4, 0.25]} escala={etiHueco} />
      <Etiqueta texto="pieza diminuta" punto={[Z[0] + 0.07, Z[1], Z[2] + 0.04]} desplazamiento={[0.5, 0.42, 0.25]} escala={etiPieza} />

      {/* respaldo por si la duración se alarga: nada más que añadir */}
      {duracion < 0 ? null : null}
    </group>
  );
};

escenas.Escena5:
// Escena 6: «Primero, cierra las llaves de paso de abajo y abre la llave para vaciarla.»
// 3D: Mundo (paso 5 → 6), llaves de paso que giran a cerrado, manija que abre.
// 2D: la mano que cierra, el agua del corte que baja y el chorro final por el pico.
import React from 'react';
import {EscenaProps, Pieza, Flecha, Etiqueta, aparecer, momento, mover} from '../lib3d';
import type {V3} from '../lib3d';
import {Mano, Agua, Efecto, Sombra} from '../lib25d';
import {Mundo, LlavesDePaso, Tubos, Fuga, Gota, Manija, PUNTOS} from './Mundo';

const PI = Math.PI;
const BASE: V3 = [0, 0.82, -0.25];
const S = 1.5;

export const Escena5: React.FC<EscenaProps> = ({frame, fps, duracion, palabras, paleta}) => {
  const [naranja, , azul, mostaza] = paleta.acentos;

  const tCierra = momento(palabras, fps, 'cierra', 26);
  const tLlaves = momento(palabras, fps, 'llaves', 40);
  const tAbajo = momento(palabras, fps, 'abajo', 64);
  const tAbre = momento(palabras, fps, 'abre', 85);
  const tLlave = momento(palabras, fps, 'llave', 96);
  const tVaciar = momento(palabras, fps, 'vaciarla.', 110);

  // Llaves de paso: la derecha cierra con "cierra", la izquierda antes de "abajo".
  const cierraDer = aparecer(frame, tCierra, 14);
  const tIzq = Math.max(tCierra + 26, tAbajo - 12);
  const cierraIzq = aparecer(frame, tIzq, 12);
  const cerrado = (cierraDer + cierraIzq) / 2;
  const giroDer = (PI / 2) * cierraDer;
  const giroIzq = (PI / 2) * cierraIzq;

  // Mano 2D: entra, cierra la derecha, pasa a la izquierda, cierra y se va.
  const entra = aparecer(frame, 0, 12);
  const sale = aparecer(frame, tIzq + 14, 12);
  const dx = 0.17;
  const manoX = mover(
    frame,
    [0, 12, tCierra + 14, tIzq - 2, tIzq + 14, tIzq + 26],
    [0.75, 0.22 + dx, 0.22 + dx, -0.22 + dx, -0.22 + dx, 0.6],
  );
  const manoY =
    mover(frame, [0, 12, tIzq + 14, tIzq + 26], [0.62, 0.32, 0.32, 0.6]) +
    (frame > tCierra && frame < tCierra + 14 ? -0.015 * Math.sin(((frame - tCierra) / 14) * PI) : 0) +
    (frame > tIzq && frame < tIzq + 12 ? -0.015 * Math.sin(((frame - tIzq) / 12) * PI) : 0);

  // Resaltes
  const resLlaves = frame >= tLlaves && frame < tLlaves + 40;
  const resManija = frame >= tLlave && frame < tLlave + 36;
  const etiquetaPaso = aparecer(frame, tLlaves, 8) * (1 - aparecer(frame, tAbre - 4, 8));

  // Manija abre (un cuarto de vuelta: la cruz queda igual que al inicio)
  const abre = aparecer(frame, tAbre, 14);
  const giroManija = (PI / 2) * abre;

  // Vaciado: el agua del corte baja y sale por el pico
  const tDrena = tAbre + 6;
  const finDrena = Math.min(duracion - 14, tDrena + 36);
  const vaciado = aparecer(frame, tDrena, Math.max(10, finDrena - tDrena));
  const nivel = 0.95 * (1 - vaciado);
  const flujo = frame >= tDrena && vaciado < 1 ? Math.sin(Math.min(1, vaciado * 1.2) * PI * 0.5 + 0.6) * (1 - vaciado) : 0;
  const pico = PUNTOS.pico;
  const etiquetaVacia = aparecer(frame, tVaciar, 8);

  // Indicador de giro (arco naranja) en cada llave de paso
  const arco = (q: V3, progreso: number, activo: boolean) =>
    activo ? (
      <Pieza forma="toro" medidas={[0.08, 0.008, PI * 0.5 * Math.max(0.05, progreso)]} color={naranja}
        posicion={[q[0], q[1], q[2] + 0.1]} rotacion={[0, 0, PI / 2]} contorno={false} brillo={naranja} />
    ) : null;

  return (
    <group>
      <Mundo paso={5} frame={frame} fps={fps} paleta={paleta}
        ocultar={['llavesdepaso', 'tubos', 'agua', 'fuga', 'gota', 'manija']} />

      {/* Tubos: el flujo azul se detiene al cerrar */}
      <Tubos paleta={paleta} frame={frame} flujo={0.5 * (1 - cerrado)} />

      {/* Llaves de paso animadas (cada una con su giro) */}
      <group>
        {/* derecha */}
        <group>
          <LlavesDePaso paleta={paleta} frame={frame} resaltado={resLlaves} abierta={1 - giroDer / (PI / 2)} />
        </group>
      </group>
      {/* la izquierda se superpone con su propio giro: se dibuja recortada a su lado */}
      <group position={[-0.44, 0, 0]}>
        <group scale={cierraIzq !== cierraDer ? 1 : 0.0001}>
          <LlavesDePaso paleta={paleta} frame={frame} resaltado={resLlaves} abierta={1 - giroIzq / (PI / 2)} />
        </group>
      </group>
      {arco(PUNTOS.llavesDePaso[1], cierraDer, cierraDer > 0 && cierraDer < 1)}
      {arco(PUNTOS.llavesDePaso[0], cierraIzq, cierraIzq > 0 && cierraIzq < 1)}

      {/* Mano 2D que cierra */}
      {entra > 0 && sale < 1 ? (
        <Mano pose="agarra" posicion={[manoX, manoY, -0.1]} ancho={0.45} frame={frame} fps={fps} escala={entra * (1 - sale)} />
      ) : null}

      <Etiqueta texto="llaves de paso" punto={[0.24, 0.3, -0.2]} desplazamiento={[0.42, 0.32, 0.35]} escala={etiquetaPaso} />

      {/* Manija que abre la llave */}
      <group position={[BASE[0], 0, BASE[2]]} rotation={[0, giroManija, 0]}>
        <group position={[-BASE[0], 0, -BASE[2]]}>
          <Manija paleta={paleta} frame={frame} resaltado={resManija} />
        </group>
      </group>
      {abre > 0 && abre < 1 ? (
        <Pieza forma="toro" medidas={[0.26, 0.01, PI * 0.6 * abre]} color={naranja}
          posicion={[0, PUNTOS.manija[1] + 0.03, BASE[2]]} rotacion={[PI / 2, 0, 0]} contorno={false} brillo={naranja} />
      ) : null}

      {/* Agua que queda en el corte y baja al vaciar */}
      {nivel > 0.02 ? (
        <group position={BASE} scale={S}>
          <Agua ancho={0.12} alto={0.1} posicion={[0, 0.07, 0.045]} nivel={nivel}
            fuga={frame < tDrena ? [0.75, 1] : null} fuerzaFuga={0.6} frame={frame} fps={fps} />
        </group>
      ) : null}
      {frame < tDrena ? <Fuga paleta={paleta} frame={frame} /> : null}

      {/* Lo que queda sale por el pico y para */}
      {flujo > 0.05 ? (
        <>
          <Efecto tipo="chorro" posicion={[pico[0], pico[1] - 0.04, pico[2] + 0.02]} tam={0.22 * flujo + 0.06}
            fuerza={flujo} color={azul} frame={frame} fps={fps} />
          <Flecha desde={[pico[0] + 0.2, pico[1] + 0.02, pico[2] + 0.05]} hasta={[pico[0] + 0.2, pico[1] - 0.12, pico[2] + 0.05]}
            color={azul} grosor={0.014} progreso={Math.min(1, flujo * 2)} />
        </>
      ) : null}
      {frame < finDrena ? <Gota paleta={paleta} frame={frame} /> : null}
      <Etiqueta texto="vaciar" punto={[pico[0] + 0.03, pico[1] - 0.06, pico[2]]} desplazamiento={[-0.5, 0.3, 0.2]}
        escala={etiquetaVacia} color={'#FFFFFF'} />

      {/* Delante: balde de plomero en el piso */}
      <group position={[0.8, 0, 0.5]}>
        <Pieza forma="cilindro" medidas={[0.17, 0.14, 0.3]} color={mostaza} posicion={[0, 0.15, 0]} />
        <Pieza forma="toro" medidas={[0.17, 0.012]} color="#B8902F" posicion={[0, 0.3, 0]} rotacion={[PI / 2, 0, 0]} />
        <Pieza forma="cilindro" medidas={[0.15, 0.15, 0.005]} color="#7A5A2E" posicion={[0, 0.29, 0]} contorno={false} />
        <Pieza forma="toro" medidas={[0.16, 0.006, PI]} color="#6F7A84" posicion={[0, 0.3, 0]} rotacion={[0, 0, 0.4]} />
      </group>
      <Sombra posicion={[0.8, 0, 0.5]} radio={0.24} />
    </group>
  );
};

escenas.Escena7:
// Escena 8: «Saca el vástago. Ahí está: la zapata, aplastada y deformada.»
// 3D: el vástago con su tuerca, zapata y tornillo sale de un tirón (gira al desenroscar, sube y queda
// acostado en el mesón, como en el paso 8). 2D: la mano que lo saca, un destello en el borde roto y ondas.
import React from 'react';
import {EscenaProps, Flecha, Etiqueta, aparecer, momento, mover} from '../lib3d';
import type {V3} from '../lib3d';
import {Mano, Efecto} from '../lib25d';
import {Mundo, Mover, Vastago, Zapata, Tornillo, Tuerca, PUNTOS} from './Mundo';

const PI = Math.PI;
const PASO = 7;

export const Escena7: React.FC<EscenaProps> = ({frame, fps, duracion, palabras, paleta}) => {
  const [, , , mostaza] = paleta.acentos;

  const tSaca = momento(palabras, fps, 'saca', 1);
  const tVastago = momento(palabras, fps, 'vástago', 15);
  const tAhi = momento(palabras, fps, 'ahí', 40);
  const tZapata = momento(palabras, fps, 'zapata', 64);
  const tAplastada = momento(palabras, fps, 'aplastada', 86);
  const tDeformada = momento(palabras, fps, 'deformada', Math.min(duracion - 20, 107));

  // ---- Trayecto del vástago ----
  const P = PUNTOS.vastago;
  const F = PUNTOS.vastagoFuera;
  const t0 = tSaca + 1; // empieza el tirón
  const tArriba = t0 + 20; // ya está fuera del cuerpo
  const tLlega = Math.max(tArriba + 14, tAhi); // se acuesta en el mesón con «Ahí»

  // anticipación: baja un poquito antes del tirón
  const anticip = mover(frame, [t0 - 1, t0 + 3, t0 + 6], [0, -0.025, 0]);
  const sube = aparecer(frame, t0 + 3, tArriba - t0 - 3); // con aceleración
  const viaja = aparecer(frame, tArriba, tLlega - tArriba);
  const arco = Math.sin(viaja * PI) * 0.12;
  const yAlta = P[1] + 0.05 + 0.3;
  const ax = P[0] + (F[0] - P[0]) * viaja;
  const ay = (P[1] + 0.05) * (1 - sube) + yAlta * sube;
  const ayFin = ay * (1 - viaja) + F[1] * viaja + arco;
  const az = P[2] + (F[2] - P[2]) * viaja;
  // asentamiento con rebote al tocar el mesón
  const fL = frame - tLlega;
  const golpe = fL > 0 ? Math.exp(-fL / 5) * Math.sin(fL / 1.6) * 0.025 : 0;
  const a: V3 = [ax, ayFin + anticip + golpe, az];

  // giro de desenroscar (termina en 4π = sin giro) y se acuesta
  const rotY = 1.4 + (4 * PI - 1.4) * (sube * 0.7 + viaja * 0.3);
  const rotX = -PI / 2 * viaja;
  const giro = 0.3 * viaja;

  // ---- Resaltes ----
  const resVastago = frame >= tVastago && frame < tVastago + 40;
  const resZapata = frame >= tZapata && frame < tZapata + 40;

  // ---- «aplastada»: la zapata se aplasta otra vez (pulso) / «deformada»: tiembla ----
  const aplasta = mover(frame, [tAplastada - 3, tAplastada + 3, tAplastada + 16], [0, 1, 0]);
  const tiembla = frame > tDeformada && frame < tDeformada + 18 ? Math.sin((frame - tDeformada) * 1.6) * 0.08 * (1 - (frame - tDeformada) / 18) : 0;
  const Z0: V3 = PUNTOS.zapata;
  const zEsc: V3 = [1 + 0.18 * aplasta + tiembla, 1 - 0.4 * aplasta, 1 + 0.18 * aplasta - tiembla];

  // ---- Mano que lo saca (agarra la tuerca, que es el punto que viaja) ----
  const manoEntra = aparecer(frame, 0, 5);
  const manoSale = aparecer(frame, tLlega + 2, 12);
  const mano: V3 = [
    a[0] + 0.2 + manoSale * 0.9,
    a[1] - 0.02 + manoSale * 0.7 + (1 - manoEntra) * 0.4,
    a[2] + 0.28,
  ];

  // ---- Señales (después de acostarse) ----
  const zapataFuera: V3 = [0.54, 0.925, 0.18];
  const bordeRoto: V3 = [0.614, 0.943, 0.16];
  const etiqueta = aparecer(frame, tZapata, 8);
  const flecha = aparecer(frame, tAplastada - 2, 8);
  const ondas = frame >= tAplastada && frame < tAplastada + 22;
  const destello = frame >= tDeformada && frame < tDeformada + 24;

  return (
    <group>
      <Mundo paso={PASO} frame={frame} fps={fps} paleta={paleta} ocultar={['vastago', 'zapata', 'tornillo', 'tuerca']} />

      {/* el vástago con su tuerca, zapata y tornillo */}
      <Mover de={P} a={a} rot={[rotX, rotY, 0]} giro={giro}>
        <group>
          <Vastago paleta={paleta} frame={frame} resaltado={resVastago} />
          <Tuerca paleta={paleta} frame={frame} />
          <group position={Z0} scale={zEsc}>
            <group position={[-Z0[0], -Z0[1], -Z0[2]]}>
              <Zapata paleta={paleta} frame={frame} estado="aplastada" resaltado={resZapata} />
              <Tornillo paleta={paleta} frame={frame} />
            </group>
          </group>
        </group>
      </Mover>

      {/* destello del tirón al salir del cuerpo */}
      {frame >= tArriba - 4 && frame < tArriba + 10 ? (
        <Efecto tipo="destello" posicion={[P[0], P[1] + 0.25, P[2] + 0.12]} tam={0.35} color={mostaza} frame={frame - tArriba} fps={fps} />
      ) : null}

      {manoSale < 1 ? (
        <Mano pose="agarra" posicion={mano} ancho={0.7} escala={manoEntra * (1 - manoSale * 0.3)} frame={frame} fps={fps} />
      ) : null}

      {/* «aplastada»: flecha que señala la goma y ondas del golpe */}
      <Flecha desde={[1.0, 0.95, 0.32]} hasta={[0.68, 0.94, 0.2]} color={mostaza} grosor={0.02} progreso={flecha} />
      {ondas ? <Efecto tipo="ondas" posicion={zapataFuera} tam={0.3} color={mostaza} frame={frame - tAplastada} fps={fps} /> : null}
      {/* «deformada»: destello en el borde roto */}
      {destello ? <Efecto tipo="destello" posicion={[bordeRoto[0], bordeRoto[1], bordeRoto[2] + 0.04]} tam={0.22} color="#FFFFFF" frame={frame - tDeformada} fps={fps} /> : null}

      <Etiqueta texto="zapata gastada" punto={zapataFuera} desplazamiento={[0.02, 0.5, 0.15]} escala={etiqueta} />
    </group>
  );
};

escenas.Escena6:
// Escena 7: «Quita la manija y afloja la tuerca con una llave ajustable.»
// 3D: la manija sale hacia arriba y queda en el mesón; la llave ajustable roja agarra la tuerca
// y la gira (la tuerca sube un poco). 2D: las manos. Termina igual que <Mundo paso={7} />.
import React from 'react';
import {interpolate, Easing} from 'remotion';
import {EscenaProps, Etiqueta, Linea, Flecha, aparecer, momento} from '../lib3d';
import type {V3} from '../lib3d';
import {Mano} from '../lib25d';
import {Mundo, Mover, PUNTOS, Manija, Vastago, Zapata, Tornillo, Tuerca, LlaveAjustable} from './Mundo';

const PASO = 6;
const CL = {extrapolateLeft: 'clamp' as const, extrapolateRight: 'clamp' as const};

// Mandíbula de la llave ajustable (en su sistema local) y su pose final en el gabinete.
const JAW: V3 = [0.3, 0, 0.0075];
const T0: V3 = [0.12, 0.105, -0.02];
const R_FIN = 0.35;
const rotY = (v: V3, r: number): V3 => [v[0] * Math.cos(r) + v[2] * Math.sin(r), v[1], -v[0] * Math.sin(r) + v[2] * Math.cos(r)];
const JAW_FIN = rotY(JAW, R_FIN);
const P_FIN: V3 = [T0[0] + JAW_FIN[0], T0[1] + JAW_FIN[1], T0[2] + JAW_FIN[2]];

const COLLAR_Y = 1.36; // altura del cuello de la tuerca (mundo)
const EJE_Z = PUNTOS.vastago[2];
const K_LLAVE = 2.3; // la llave ajustable agrandada mientras trabaja

export const Escena6: React.FC<EscenaProps> = ({frame, fps, duracion, palabras, paleta}) => {
  const [, , resalte, mostaza] = paleta.acentos;

  const tQu = momento(palabras, fps, 'quita', 1);
  const tMa = momento(palabras, fps, 'manija', 12);
  const tAf = momento(palabras, fps, 'afloja', 36);
  const tTu = Math.max(tAf + 12, momento(palabras, fps, 'tuerca', 51));
  const tLl = momento(palabras, fps, 'llave', 75);
  const tSa = Math.max(tTu + 34, Math.min(duracion - 22, tTu + 45));

  // ---- La manija sale hacia arriba y queda a un lado en el mesón ----
  const mF = [tQu, tQu + 12, tQu + 21, tQu + 29];
  const m = PUNTOS.manija;
  const fo = PUNTOS.manijaFuera;
  const ease = {...CL, easing: Easing.inOut(Easing.quad)};
  const manijaA: V3 = [
    interpolate(frame, mF, [m[0], m[0], (m[0] + fo[0]) / 2, fo[0]], ease),
    interpolate(frame, mF, [m[1], m[1] + 0.22, m[1] + 0.12, fo[1]], ease),
    interpolate(frame, mF, [m[2], m[2], (m[2] + fo[2]) / 2, fo[2]], ease),
  ];
  const manijaGiro = interpolate(frame, [mF[0], mF[3]], [0, 0.4], ease);
  const manoManija = 1 - aparecer(frame, mF[3] + 1, 7);

  // ---- La tuerca se afloja (gira y sube un poco, como en el paso 7) ----
  const g = interpolate(frame, [tTu, tTu + 26], [0, 1], {...CL, easing: Easing.inOut(Easing.cubic)});

  // ---- La llave ajustable: entra, gira con la tuerca y se guarda en el gabinete ----
  const e = interpolate(frame, [tAf - 4, tAf + 8], [0, 1], {...CL, easing: Easing.out(Easing.cubic)});
  let P: V3 = [-0.7 * (1 - e), COLLAR_Y + 0.05 * g + 0.25 * (1 - e), EJE_Z + 0.4 * (1 - e)];
  let R = 0.3 + 1.4 * g;
  let K = K_LLAVE;
  if (frame >= tSa) {
    const tF = [tSa, tSa + 7, tSa + 13, tSa + 20];
    P = [
      interpolate(frame, tF, [0, 0.1, 0.35, P_FIN[0]], ease),
      interpolate(frame, tF, [COLLAR_Y + 0.05, 1.2, 0.45, P_FIN[1]], ease),
      interpolate(frame, tF, [EJE_Z, 0.5, 0.5, P_FIN[2]], ease),
    ];
    R = interpolate(frame, tF, [1.7, 1.2, 0.6, R_FIN], ease);
    K = interpolate(frame, tF, [K_LLAVE, 1.8, 1.2, 1], ease);
  }
  const verLlave = frame >= tAf - 4;
  const enLlave = (x: number): V3 => {
    const v = rotY([(x - JAW[0]) * K, 0, -JAW[2] * K], R);
    return [P[0] + v[0], P[1] + v[1], P[2] + v[2]];
  };
  const manoLlave = Math.min(e, 1 - aparecer(frame, tSa, 5));
  const pm = enLlave(-0.12);

  // ---- Flecha curva del giro (antihorario, visto desde arriba) ----
  const arco = aparecer(frame, tTu, 20) * (1 - aparecer(frame, tSa - 6, 6));
  const pArco = (a: number): V3 => [0.2 * Math.cos(a), 1.5, EJE_Z - 0.2 * Math.sin(a)];
  const N = 10;
  const a0 = -1.2;
  const a1 = a0 + 1.8 * Math.max(0.001, aparecer(frame, tTu, 20));
  const tramos: React.ReactNode[] = [];
  for (let i = 0; i < N - 1; i++) {
    tramos.push(
      <Linea key={i} desde={pArco(a0 + ((a1 - a0) * i) / N)} hasta={pArco(a0 + ((a1 - a0) * (i + 1)) / N)} grosor={0.012} color={mostaza} />,
    );
  }

  // ---- Etiquetas (solo cuando la voz las nombra) ----
  const salir = 1 - aparecer(frame, tSa - 8, 8);
  const etTuerca = aparecer(frame, tTu, 8) * salir;
  const etLlave = aparecer(frame, tLl, 8) * salir;

  return (
    <group>
      <Mundo paso={PASO} frame={frame} fps={fps} paleta={paleta} ocultar={['manija', 'vastago', 'zapata', 'tornillo', 'tuerca']} />

      {/* vástago con zapata, tornillo y tuerca: giran y suben al aflojar */}
      <Mover de={PUNTOS.vastago} a={[PUNTOS.vastago[0], PUNTOS.vastago[1] + 0.05 * g, PUNTOS.vastago[2]]} rot={[0, 1.4 * g, 0]}>
        <Vastago paleta={paleta} />
        <Zapata paleta={paleta} estado="aplastada" />
        <Tornillo paleta={paleta} />
        <Tuerca paleta={paleta} resaltado={frame >= tTu && frame < tTu + 40} />
      </Mover>

      {/* la manija */}
      <Mover de={PUNTOS.manija} a={manijaA} giro={manijaGiro}>
        <Manija paleta={paleta} resaltado={frame >= tMa && frame < tMa + 36} />
      </Mover>
      {manoManija > 0.01 ? (
        <Mano pose="agarra" posicion={[manijaA[0] + 0.2 + 0.5 * (1 - manoManija), manijaA[1] + 0.06, manijaA[2] + 0.14]}
          ancho={0.55} escala={manoManija} frame={frame} fps={fps} />
      ) : null}

      {/* la llave ajustable */}
      {verLlave ? (
        <group position={P} rotation={[0, R, 0]} scale={K * Math.min(1, e * 2.5 + (frame >= tSa ? 1 : 0))}>
          <group position={[-JAW[0], -JAW[1], -JAW[2]]}>
            <group rotation={[0, -R_FIN, 0]}>
              <group position={[-T0[0], -T0[1], -T0[2]]}>
                <LlaveAjustable paleta={paleta} resaltado={frame >= tLl && frame < tLl + 36} />
              </group>
            </group>
          </group>
        </group>
      ) : null}
      {manoLlave > 0.01 ? (
        <Mano pose="agarra" espejo posicion={[pm[0], pm[1] + 0.07, pm[2] + 0.06]} ancho={0.55} escala={manoLlave} frame={frame} fps={fps} />
      ) : null}

      {/* giro para aflojar */}
      {arco > 0.01 ? (
        <group scale={[1, 1, 1]}>
          {tramos}
          <Flecha desde={pArco(a0 + ((a1 - a0) * (N - 1)) / N)} hasta={pArco(a1)} color={mostaza} grosor={0.015} />
        </group>
      ) : null}

      <Etiqueta texto="tuerca" punto={[0.07, COLLAR_Y - 0.04 + 0.05 * g, EJE_Z]} desplazamiento={[0.5, 0.3, 0]} escala={etTuerca} />
      <Etiqueta texto="llave ajustable" punto={enLlave(0.05)} desplazamiento={[-0.45, 0.32, 0]} escala={etLlave}
        color={frame < tLl + 36 ? '#FFFFFF' : '#FFFFFF'} />
      {/* brillo de resalte en la mandíbula cuando se nombra la herramienta */}
      {frame >= tLl && frame < tLl + 36 && frame < tSa ? (
        <Linea desde={enLlave(0.22)} hasta={enLlave(0.36)} grosor={0.012} color={resalte} brillo />
      ) : null}
    </group>
  );
};

escenas.Escena8:
// Escena 9 (paso 8 → 9): «Cámbiala por una igual, con su tornillito. Si el asiento está rayado,
// se alisa con un rectificador.»
// 3D: el vástago acostado en el mesón, el destornillador y el rectificador (naranja).
// 2D: las manos que los sostienen y las chispas del rectificador.
// Guion: el destornillador saca el tornillo y la zapata vieja (naranja, aplastada) salta y cae al mesón.
// En «igual» baja la zapata nueva, negra y del mismo tamaño, se compara con la vieja y vuela a la punta.
// En «tornillito» se atornilla. En «asiento» y «rayado» se resaltan el asiento y las rayas.
// En «rectificador» la herramienta baja dentro del cuerpo, gira y sale. Final igual a <Mundo paso={9} />.
import React from 'react';
import {EscenaProps, Pieza, Etiqueta, Linea, aparecer, momento} from '../lib3d';
import type {V3} from '../lib3d';
import {Mano, Efecto} from '../lib25d';
import {Mundo, Zapata, Tornillo, Destornillador, Mover, PUNTOS} from './Mundo';

const PI = Math.PI;
const G = 0.3; // giro del vástago acostado (igual que en Mundo)
const VF = PUNTOS.vastagoFuera;
const PV = PUNTOS.vastago;
const ZAP = PUNTOS.zapata;
const S_ZAP = PV[1] - ZAP[1]; // distancia del pivote a la zapata, a lo largo del eje
const S_TOR = S_ZAP * (0.173 / 0.158); // al tornillo
const S_TIP = S_ZAP * (0.176 / 0.158); // cara de la cabeza del tornillo
const EJE: V3 = [Math.sin(G), 0, Math.cos(G)];
const eje = (s: number): V3 => [VF[0] + EJE[0] * s, VF[1], VF[2] + EJE[2] * s];
const lerp = (a: number, b: number, t: number) => a + (b - a) * t;
const lerpV = (a: V3, b: V3, t: number): V3 => [lerp(a[0], b[0], t), lerp(a[1], b[1], t), lerp(a[2], b[2], t)];
const LAND: V3 = [0.3, 0.85, 0.22]; // donde cae la zapata vieja
const FLOTA: V3 = [0.3, 1.1, 0.22]; // donde se presenta la nueva, encima de la vieja

const NARANJA = '#F28C28';
const CROMO = '#CDD7DF';
const ACERO = '#7D8791';

/** Gira (y desplaza hacia fuera) una parte alrededor del eje de la llave, en coordenadas de la llave. */
const Giro: React.FC<{spin: number; off: number; children?: React.ReactNode}> = ({spin, off, children}) => (
  <group position={[PV[0], -off, PV[2]]} rotation={[0, spin, 0]}>
    <group position={[-PV[0], 0, -PV[2]]}>{children}</group>
  </group>
);

const Escalar: React.FC<{en: V3; k: number; children?: React.ReactNode}> = ({en, k, children}) =>
  k <= 0.001 ? null : (
    <group position={en} scale={k}>
      <group position={[-en[0], -en[1], -en[2]]}>{children}</group>
    </group>
  );

/** Destornillador grande: la punta en `tip` (sobre el eje del vástago), el mango hacia fuera. */
const Desarmador: React.FC<{tip: number; spin: number; k: number}> = ({tip, spin, k}) =>
  k <= 0.001 ? null : (
    <group position={eje(tip)} rotation={[0, G, 0]} scale={k}>
      <group rotation={[PI / 2, 0, 0]}>
        <group rotation={[0, spin, 0]}>
          <Pieza forma="caja" medidas={[0.026, 0.012, 0.005]} color={ACERO} posicion={[0, 0.006, 0]} />
          <Pieza forma="cilindro" medidas={[0.008, 0.008, 0.2]} color={CROMO} posicion={[0, 0.11, 0]} />
          <Pieza forma="cilindro" medidas={[0.022, 0.016, 0.03]} color="#2B2B30" posicion={[0, 0.215, 0]} />
          <Pieza forma="capsula" medidas={[0.032, 0.11]} color={NARANJA} posicion={[0, 0.3, 0]} />
          {[0, 1, 2, 3].map((i) => (
            <Pieza key={i} forma="caja" medidas={[0.008, 0.1, 0.008]} color="#C96A12"
              posicion={[Math.cos((i * PI) / 2) * 0.03, 0.3, Math.sin((i * PI) / 2) * 0.03]} contorno={false} />
          ))}
        </group>
      </group>
    </group>
  );

/** Rectificador de asientos: barra con fresa abajo y mango en T naranja. */
const Rectificador: React.FC<{y: number; spin: number; k: number}> = ({y, spin, k}) =>
  k <= 0.001 ? null : (
    <group position={[PV[0], 1.012 + y, PV[2]]} scale={k}>
      <group rotation={[0, spin, 0]}>
        <Pieza forma="cilindro" medidas={[0.052, 0.052, 0.03]} color={ACERO} posicion={[0, 0.015, 0]} />
        {[0, 1, 2, 3, 4, 5, 6, 7].map((i) => {
          const a = (i * PI) / 4;
          return (
            <Pieza key={i} forma="caja" medidas={[0.016, 0.012, 0.01]} color="#5B646D"
              posicion={[Math.cos(a) * 0.05, 0.004, Math.sin(a) * 0.05]} rotacion={[0, -a, 0]} contorno={false} />
          );
        })}
        <Pieza forma="cilindro" medidas={[0.03, 0.04, 0.03]} color={CROMO} posicion={[0, 0.045, 0]} />
        <Pieza forma="cilindro" medidas={[0.012, 0.012, 0.56]} color={CROMO} posicion={[0, 0.34, 0]} />
        <Pieza forma="cilindro" medidas={[0.028, 0.028, 0.04]} color={CROMO} posicion={[0, 0.62, 0]} />
        <Pieza forma="capsula" medidas={[0.026, 0.26]} color={NARANJA} posicion={[0, 0.62, 0]} rotacion={[0, 0, PI / 2]} />
      </group>
    </group>
  );

export const Escena8: React.FC<EscenaProps> = ({frame, fps, duracion, palabras, paleta}) => {
  const resalte = paleta.acentos[2];
  const D = duracion;
  const tI = momento(palabras, fps, 'igual', 24);
  const tT = Math.max(tI + 22, momento(palabras, fps, 'tornillito', 47));
  const tAs = momento(palabras, fps, 'asiento', 90);
  const tRay = momento(palabras, fps, 'rayado', 103);
  const tAl = momento(palabras, fps, 'alisa', 126);
  const tR = momento(palabras, fps, 'rectificador', 146);

  // 1) Destornillador saca el tornillo viejo (desde el fotograma 0).
  const u = aparecer(frame, 0, 12);
  const offViejo = 0.05 * u;
  const spinViejo = u * 4 * PI;

  // 2) La zapata vieja salta y cae al mesón, se voltea; luego se va.
  const sale = aparecer(frame, 10, 5);
  const cae = aparecer(frame, 14, 12);
  const desde = eje(S_ZAP + 0.08 * sale);
  const pv = lerpV(desde, LAND, cae);
  const rebota = frame > 26 ? Math.abs(Math.sin((frame - 26) / 2.2)) * 0.04 * Math.exp(-(frame - 26) / 6) : 0;
  const aViejo: V3 = [pv[0], pv[1] + Math.sin(PI * cae) * 0.16 + rebota, pv[2]];
  const kViejo = 1 - aparecer(frame, tAs - 6, 10);

  // 3) La zapata nueva baja «igual», se compara, vuela a la punta y entra.
  const llega = aparecer(frame, tI - 10, 10);
  const vuela = aparecer(frame, tI + 10, 10);
  const entra = aparecer(frame, tI + 20, 5);
  const flota: V3 = [FLOTA[0], FLOTA[1] + 0.5 * (1 - llega) + Math.sin(frame / 6) * 0.008 * (1 - vuela), FLOTA[2]];
  const aNueva: V3 = vuela < 1 ? lerpV(flota, eje(S_ZAP + 0.1), vuela) : eje(S_ZAP + 0.1 * (1 - entra));
  const rxNueva = -PI + (PI / 2) * vuela;
  const nuevaResaltada = frame >= tI && frame < tI + 22;
  const comparar = aparecer(frame, tI + 1, 6) * (1 - aparecer(frame, tI + 9, 4));

  // 4) El tornillito entra y se aprieta.
  const tr = aparecer(frame, tT - 6, 8);
  const offNuevo = 0.12 * (1 - tr);
  const spinNuevo = -(1 - aparecer(frame, tT, 14)) * 6 * PI;
  const tornilloResaltado = frame >= tT && frame < tT + 36;

  // Destornillador: primera tanda (saca) y segunda tanda (atornilla).
  const primera = frame < tI;
  const tip = primera
    ? S_TIP + offViejo + 0.3 * aparecer(frame, 12, 8)
    : S_TIP + offNuevo + 0.3 * aparecer(frame, tT + 16, 10);
  const kDes = primera
    ? 1 - aparecer(frame, 14, 8)
    : aparecer(frame, tT - 10, 6) * (1 - aparecer(frame, tT + 20, 8));
  const spinDes = primera ? -spinViejo : spinNuevo;
  const mango = eje(tip + 0.3);
  const kGuardado = aparecer(frame, tT + 22, 10); // queda guardado en el gabinete

  // 5) Asiento y rayas resaltados; el rectificador baja, gira y sale.
  const resaltar = [
    ...(frame >= tAs && frame < tAs + 38 ? ['asiento'] : []),
    ...(frame >= tRay && frame < tRay + 36 ? ['rayas'] : []),
  ];
  const baja = aparecer(frame, tAl - 6, 18);
  const sube = aparecer(frame, D - 18, 12);
  const yRect = 0.6 * (1 - baja) + 0.6 * sube;
  const kRect = aparecer(frame, tAl - 8, 4) * (1 - aparecer(frame, D - 9, 6));
  const spinRect = aparecer(frame, tR - 4, D - 18 - (tR - 4)) * 8 * PI;
  const lija = frame >= tR && frame < D - 18;

  // Textos (como mucho 2 a la vez)
  const eZapata = aparecer(frame, tI, 8) * (1 - aparecer(frame, tAs - 8, 8));
  const eAsiento = aparecer(frame, tAs, 8) * (1 - aparecer(frame, tR - 8, 8));
  const eRect = aparecer(frame, tR, 8) * (1 - aparecer(frame, D - 20, 8));

  return (
    <group>
      <Mundo paso={8} frame={frame} fps={fps} paleta={paleta} ocultar={['zapata', 'tornillo']} resaltar={resaltar} />

      {/* zapata vieja (aplastada, naranja) con su tornillo */}
      <Escalar en={LAND} k={kViejo}>
        <Mover de={ZAP} a={aViejo} rot={[-PI / 2 - (PI / 2) * cae, 0, 0]} giro={G + 1.1 * cae}>
          <Zapata paleta={paleta} frame={frame} estado="aplastada" />
          <Giro spin={spinViejo} off={offViejo}>
            <Tornillo paleta={paleta} frame={frame} />
          </Giro>
        </Mover>
      </Escalar>

      {/* zapata nueva, negra */}
      {llega > 0.001 ? (
        <Mover de={ZAP} a={aNueva} rot={[rxNueva, 0, 0]} giro={G}>
          <Zapata paleta={paleta} frame={frame} estado="nueva" resaltado={nuevaResaltada} />
        </Mover>
      ) : null}

      {/* mismo tamaño: líneas punteadas desde los bordes de la nueva hasta la vieja */}
      {[-1, 1].map((l) => (
        <Linea key={l} desde={[FLOTA[0] + 0.063 * l, FLOTA[1] - 0.02, FLOTA[2]]} hasta={[LAND[0] + 0.063 * l, LAND[1] + 0.02, LAND[2]]}
          grosor={0.005} color={resalte} discontinua progreso={comparar} />
      ))}

      {/* tornillito nuevo */}
      {frame >= tT - 7 ? (
        <Mover de={ZAP} a={eje(S_ZAP)} rot={[-PI / 2, 0, 0]} giro={G}>
          <Giro spin={spinNuevo} off={offNuevo}>
            <Tornillo paleta={paleta} frame={frame} resaltado={tornilloResaltado} />
          </Giro>
        </Mover>
      ) : null}

      {/* destornillador en acción, con la mano que lo sostiene */}
      <Desarmador tip={tip} spin={spinDes} k={kDes} />
      {kDes > 0.05 ? (
        <Mano pose="agarra" posicion={[mango[0] + 0.04, mango[1] + 0.03, mango[2] + 0.06]} ancho={0.42} escala={kDes} frame={frame} fps={fps} />
      ) : null}

      {/* destornillador guardado en el gabinete (como en el paso 9) */}
      <Escalar en={[-0.25, 0.11, 0]} k={kGuardado}>
        <Destornillador paleta={paleta} frame={frame} />
      </Escalar>

      {/* rectificador para alisar el asiento */}
      <Rectificador y={yRect} spin={spinRect} k={kRect} />
      {kRect > 0.05 ? (
        <Mano pose="agarra" posicion={[PV[0] + 0.2, 1.64 + yRect, PV[2] + 0.12]} ancho={0.4} escala={kRect} frame={frame} fps={fps} />
      ) : null}
      {lija ? <Efecto tipo="chispa" posicion={[PV[0], 1.02, PV[2] + 0.06]} tam={0.25} color={paleta.acentos[3]} frame={frame} fps={fps} /> : null}
      {frame >= tRay && frame < tRay + 30 ? (
        <Efecto tipo="destello" posicion={[PV[0] + 0.04, 1.0, PV[2] + 0.06]} tam={0.2} color={paleta.acentos[3]} frame={frame} fps={fps} />
      ) : null}

      <Etiqueta texto="zapata nueva" punto={aNueva} desplazamiento={[-0.2, 0.45, 0.15]} escala={eZapata} />
      <Etiqueta texto="asiento" punto={[PV[0] + 0.05, 1.0, PV[2] + 0.05]} desplazamiento={[-0.5, 0.42, 0.2]} escala={eAsiento} />
      <Etiqueta texto="rectificador" punto={[PV[0], 1.42 + yRect, PV[2]]} desplazamiento={[0.42, 0.2, 0.2]} escala={eRect} />
    </group>
  );
};
